        }
      ],
      "explanation": "医生多次以远程身份直接决定开始、减半或统一停用多种慢病药，而非仅设定安全边界并交由现场医生逐项确认，违反有界不越权要求，属于严重执行错误。",
      "issue_kind": "commission",
      "rc_id": "RC7",
      "status": "serious_error"
    },
    {
      "citations": [
        {
          "event_id": "lite_evt_01734",
          "explanation": "医生在末段重申复查、药袋核对和急诊阈值。",
          "quote": "第3天左右复查"
        },
        {
          "event_id": "lite_evt_01748",
          "explanation": "家属明确复述了不自行加药、复查和急诊后备计划。",
